 68	     */
 69	    public double act(List<Creature> newAnimals, boolean atDayTime, double oxygenLevel, Disease disease, int step)
 70	    {
 71	        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED){
 72	            setDead();
 73	            return 0;
 74	        }
 75	
 76	        // If the animal dies of disease, it will consume no oxygen.
 77	        if(disease.progressInfection(this, step))
